import { FolderGit2, FolderPlus, LayoutDashboard, PanelLeftClose, Plus, Search, Settings2 } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { shortcutLabel } from "../lib/shortcuts";
import type { RegisteredProject } from "../lib/tauri";
import type { ActiveAgent, DirtyState, Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { SectionHeader } from "./ui/SectionHeader";
import { WorktreeList } from "./WorktreeList";

export const SIDEBAR_WIDTH_STORAGE_KEY = "orca.sidebar.width";
const DEFAULT_SIDEBAR_WIDTH = 236;
const MIN_SIDEBAR_WIDTH = 220;
const MAX_SIDEBAR_WIDTH = 420;

type SidebarProps = {
  projects?: RegisteredProject[];
  activeProjectId?: string;
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  statuses?: Record<string, DirtyState | undefined>;
  onSelectProject?: (project: RegisteredProject) => void;
  onAddProject?: () => void;
  onSelectWorktree: (worktree: Worktree) => void;
  onCreateWorktree: () => void;
  onRefreshWorktreeStatus?: (worktree: Worktree) => void;
  onDeleteWorktree?: (worktree: Worktree) => void;
  onOpenCommandPalette: () => void;
  onOpenSettings?: () => void;
};

export function Sidebar({
  projects = [],
  activeProjectId,
  worktrees,
  agents,
  activePath,
  statuses = {},
  onSelectProject = () => undefined,
  onAddProject = () => undefined,
  onSelectWorktree,
  onCreateWorktree,
  onRefreshWorktreeStatus = () => undefined,
  onDeleteWorktree = () => undefined,
  onOpenCommandPalette,
  onOpenSettings,
}: SidebarProps) {
  const worktreeRegionRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const [width, setWidth] = useState(loadSidebarWidth);
  const widthRef = useRef(width);
  widthRef.current = width;

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const nextWidth = clampSidebarWidth(drag.startWidth + event.clientX - drag.startX);
      widthRef.current = nextWidth;
      setWidth(nextWidth);
    };

    const finishDrag = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      persistSidebarWidth(widthRef.current);
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, []);

  const focusWorktrees = () => {
    worktreeRegionRef.current?.focus();
    worktreeRegionRef.current?.scrollIntoView?.({ block: "start" });
  };

  const startResize = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    dragRef.current = { startX: event.clientX, startWidth: widthRef.current };
    document.body.style.cursor = "col-resize";
  };

  return (
    <aside
      className="relative flex h-full shrink-0 flex-col overflow-hidden border-r border-worktree-sidebar-border bg-worktree-sidebar text-worktree-sidebar-foreground"
      style={{ width: `${width}px`, minWidth: `${MIN_SIDEBAR_WIDTH}px`, maxWidth: `${MAX_SIDEBAR_WIDTH}px` }}
    >
      <div
        data-testid="sidebar-drag-region"
        data-tauri-drag-region
        className="drag-region flex h-titlebar shrink-0 items-center justify-end px-2"
      >
        <IconButton label="Hide sidebar" className="no-drag" size="sm">
          <PanelLeftClose className="size-3.5" />
        </IconButton>
      </div>

      <div className="space-y-1 px-2 pb-1">
        <button
          type="button"
          onClick={focusWorktrees}
          className="flex h-7 w-full items-center gap-2 rounded-md bg-worktree-sidebar-accent px-2 text-left text-[13px] font-medium tracking-tight text-worktree-sidebar-accent-foreground"
        >
          <LayoutDashboard className="size-3.5" />
          <span className="flex-1">Workspace</span>
        </button>
        <button
          type="button"
          onClick={onOpenCommandPalette}
          className="group relative flex h-7 w-full items-center rounded-md border border-worktree-sidebar-border/70 bg-worktree-sidebar-foreground/5 pl-7 pr-1.5 text-left text-[12px] font-medium tracking-tight text-worktree-sidebar-foreground/45 transition-colors hover:border-worktree-sidebar-border hover:bg-worktree-sidebar-foreground/8"
        >
          <Search className="pointer-events-none absolute left-2 top-1/2 size-3 -translate-y-1/2 text-worktree-sidebar-foreground/30" />
          Search workspaces
          <kbd className="ml-auto rounded border border-worktree-sidebar-border/80 bg-worktree-sidebar-foreground/8 px-1 py-px text-[9px] text-worktree-sidebar-foreground/55">
            {shortcutLabel("commandPalette.open")}
          </kbd>
        </button>
      </div>

      <div className="shrink-0 border-b border-worktree-sidebar-border pb-1">
        <SectionHeader
          title="Projects"
          count={projects.length}
          actions={
            <IconButton label="Add project" size="sm" onClick={onAddProject}>
              <Plus className="size-3.5" />
            </IconButton>
          }
        />
        <div className="space-y-0.5 px-2">
          {projects.map((project) => {
            const active = project.workspaceId === activeProjectId;
            return (
              <button
                key={project.workspaceId}
                type="button"
                onClick={() => onSelectProject(project)}
                className={`flex h-7 w-full items-center gap-2 rounded-md px-2 text-left text-[12px] transition-colors ${
                  active
                    ? "bg-worktree-sidebar-accent text-worktree-sidebar-accent-foreground"
                    : "text-worktree-sidebar-foreground/65 hover:bg-worktree-sidebar-accent/60 hover:text-worktree-sidebar-foreground"
                }`}
              >
                <FolderGit2 className="size-3.5 shrink-0" />
                <span className="min-w-0 flex-1 truncate">{project.workspaceId}</span>
              </button>
            );
          })}
        </div>
      </div>

      <div ref={worktreeRegionRef} tabIndex={-1} data-testid="worktree-region" className="flex min-h-0 flex-1 flex-col outline-none">
        <SectionHeader
          title="Worktrees"
          count={worktrees.length}
          actions={
            <IconButton label="Add worktree" size="sm" onClick={onCreateWorktree}>
              <FolderPlus className="size-3.5" />
            </IconButton>
          }
        />
        <WorktreeList
          worktrees={worktrees}
          agents={agents}
          activePath={activePath}
          statuses={statuses}
          onSelect={onSelectWorktree}
          onCreate={onCreateWorktree}
          onRefreshStatus={onRefreshWorktreeStatus}
          onDelete={onDeleteWorktree}
        />
      </div>

      <div className="flex shrink-0 items-center justify-between border-t border-worktree-sidebar-border px-2 py-1.5">
        <div className="flex items-center gap-2 px-1 text-[10px] text-muted-foreground">
          <span className="size-1.5 rounded-full bg-status-success" />
          Local runtime
        </div>
        <IconButton label="Settings" size="sm" onClick={onOpenSettings}>
          <Settings2 className="size-3.5" />
        </IconButton>
      </div>

      <div
        role="separator"
        aria-label="Resize sidebar"
        aria-orientation="vertical"
        aria-valuemin={MIN_SIDEBAR_WIDTH}
        aria-valuemax={MAX_SIDEBAR_WIDTH}
        aria-valuenow={width}
        onPointerDown={startResize}
        className="no-drag absolute inset-y-0 right-0 z-30 w-1.5 cursor-col-resize touch-none"
      >
        <span className="pointer-events-none absolute inset-y-0 right-0 w-px bg-worktree-sidebar-border transition-colors group-hover:bg-ring/45" />
      </div>
    </aside>
  );
}

function loadSidebarWidth() {
  try {
    const stored = Number(window.localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY));
    return Number.isFinite(stored) && stored > 0 ? clampSidebarWidth(stored) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

function persistSidebarWidth(width: number) {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(width)));
  } catch {
    // A storage failure should not break pointer resizing for this session.
  }
}

function clampSidebarWidth(width: number) {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, Math.round(width)));
}

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type { Worktree } from "../lib/types";
import { SIDEBAR_WIDTH_STORAGE_KEY, Sidebar } from "./Sidebar";

const worktree: Worktree = {
  path: "/repo/main",
  head: "abc123",
  branch: "refs/heads/orca/ws/main",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

beforeEach(() => localStorage.clear());
afterEach(cleanup);

function baseProps(overrides: Record<string, unknown> = {}) {
  return {
    worktrees: [worktree],
    agents: [],
    activePath: worktree.path,
    onSelectWorktree: vi.fn(),
    onCreateWorktree: vi.fn(),
    onAddProject: vi.fn(),
    onOpenCommandPalette: vi.fn(),
    onOpenSettings: vi.fn(),
    ...overrides,
  } as any;
}

function renderSidebar(overrides: Record<string, unknown> = {}) {
  return render(<Sidebar {...baseProps(overrides)} />);
}

describe("Sidebar navigation", () => {
  it("uses the 236px parity width by default", () => {
    renderSidebar();
    expect(screen.getByRole("complementary")).toHaveStyle({ width: "236px" });
  });

  it("keeps Workspace and Search functional and exposes Add Project", () => {
    const onOpenCommandPalette = vi.fn();
    const onAddProject = vi.fn();
    renderSidebar({ onOpenCommandPalette, onAddProject });

    expect(screen.queryByText("Agents")).not.toBeInTheDocument();
    expect(screen.queryByText("Active agents")).not.toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: /search workspaces/i }));
    expect(onOpenCommandPalette).toHaveBeenCalledOnce();

    fireEvent.click(screen.getByRole("button", { name: "Workspace" }));
    expect(screen.getByTestId("worktree-region")).toHaveFocus();

    fireEvent.click(screen.getByRole("button", { name: "Add project" }));
    expect(onAddProject).toHaveBeenCalledOnce();
  });

  it("marks only the noninteractive titlebar background as a Tauri drag region", () => {
    renderSidebar();
    const dragBackground = screen.getByTestId("sidebar-drag-region");
    expect(dragBackground).toHaveAttribute("data-tauri-drag-region");
    expect(screen.getByRole("button", { name: "Hide sidebar" })).toHaveClass("no-drag");
    expect(screen.getByRole("separator", { name: "Resize sidebar" })).toHaveClass("no-drag");
  });

  it("restores, drags, clamps, and persists sidebar width", () => {
    localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, "390");
    renderSidebar();

    const sidebar = screen.getByRole("complementary");
    const handle = screen.getByRole("separator", { name: "Resize sidebar" });
    expect(sidebar).toHaveStyle({ width: "390px" });

    fireEvent.pointerDown(handle, { clientX: 390, pointerId: 1 });
    fireEvent.pointerMove(window, { clientX: 600, pointerId: 1 });
    expect(sidebar).toHaveStyle({ width: "420px" });
    fireEvent.pointerUp(window, { clientX: 600, pointerId: 1 });
    expect(localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY)).toBe("420");

    fireEvent.pointerDown(handle, { clientX: 420, pointerId: 2 });
    fireEvent.pointerMove(window, { clientX: 40, pointerId: 2 });
    expect(sidebar).toHaveStyle({ width: "220px" });
    fireEvent.pointerUp(window, { clientX: 40, pointerId: 2 });
    expect(localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY)).toBe("220");
  });
});

import { Plus, TerminalSquare, X } from "lucide-react";
import type { ReactNode } from "react";

import { cn } from "../lib/cn";
import type { TerminalTab } from "../lib/types";
import { IconButton } from "./ui/IconButton";

type TabBarProps = {
  tabs: TerminalTab[];
  activeTabId: string;
  onActivate: (id: string) => void;
  onClose: (id: string) => void;
  onAdd: () => void;
  actions?: ReactNode;
  showAdd?: boolean;
};

export function TabBar({ tabs, activeTabId, onActivate, onClose, onAdd, actions, showAdd = true }: TabBarProps) {
  return (
    <div data-testid="tab-strip" className="flex h-tabbar shrink-0 items-stretch border-b border-border bg-card pr-1">
      <div className="flex min-w-0 flex-1 items-stretch overflow-x-auto scrollbar-none">
        {tabs.map((tab) => {
          const active = tab.id === activeTabId;
          return (
            <button
              key={tab.id}
              type="button"
              onClick={() => onActivate(tab.id)}
              className={cn(
                "group relative flex min-w-tab max-w-tab items-center gap-1.5 border-r border-border px-2 text-[12px] transition-colors",
                active ? "bg-terminal text-foreground" : "bg-card text-muted-foreground hover:bg-accent/45 hover:text-foreground",
              )}
            >
              <TerminalSquare className="size-3 shrink-0" />
              <span className="min-w-0 flex-1 truncate text-left">{tab.label}</span>
              <span
                role="button"
                tabIndex={0}
                aria-label={`Close ${tab.label}`}
                onClick={(event) => {
                  event.stopPropagation();
                  onClose(tab.id);
                }}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    event.stopPropagation();
                    onClose(tab.id);
                  }
                }}
                className="no-drag rounded p-0.5 text-muted-foreground opacity-0 hover:bg-muted hover:text-foreground group-hover:opacity-100 focus:opacity-100"
              >
                <X className="size-3" />
              </span>
              {active ? (
                <span data-testid="tab-active-indicator" className="pointer-events-none absolute inset-x-0 bottom-0 h-px bg-foreground" />
              ) : null}
            </button>
          );
        })}
      </div>
      {showAdd ? (
        <IconButton label="New terminal" size="sm" className="no-drag my-auto ml-1" onClick={onAdd}>
          <Plus className="size-3.5" />
        </IconButton>
      ) : null}
      {actions ? <div className="no-drag ml-0.5 flex shrink-0 items-center gap-0.5">{actions}</div> : null}
    </div>
  );
}

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { TabBar } from "./TabBar";

afterEach(cleanup);

describe("TabBar", () => {
  it("routes activate, close, and new-tab actions through real callbacks", () => {
    const onActivate = vi.fn();
    const onClose = vi.fn();
    const onAdd = vi.fn();
    render(
      <TabBar
        tabs={[
          { id: "tab-a", label: "main", sessionId: "session-a" },
          { id: "tab-b", label: "feature", sessionId: "session-b" },
        ]}
        activeTabId="tab-a"
        onActivate={onActivate}
        onClose={onClose}
        onAdd={onAdd}
      />,
    );

    const featureLabel = screen.getByText("feature");
    fireEvent.click(featureLabel.closest("button")!);
    expect(onActivate).toHaveBeenCalledWith("tab-b");

    fireEvent.click(screen.getByRole("button", { name: "Close main" }));
    expect(onClose).toHaveBeenCalledWith("tab-a");

    fireEvent.click(screen.getByRole("button", { name: "New terminal" }));
    expect(onAdd).toHaveBeenCalledOnce();
  });

  it("uses low-chrome 32px geometry and a one-pixel active indicator", () => {
    render(
      <TabBar
        tabs={[{ id: "tab-a", label: "main", sessionId: "session-a" }]}
        activeTabId="tab-a"
        onActivate={vi.fn()}
        onClose={vi.fn()}
        onAdd={vi.fn()}
      />,
    );

    expect(screen.getByTestId("tab-strip")).toHaveClass("h-tabbar");
    expect(screen.getByTestId("tab-active-indicator")).toHaveClass("h-px");
  });
});

